def is_match_brute(query, pattern):
    # Conceptually: try every way of choosing positions in query that
    # correspond to pattern's characters (a subsequence match), then verify
    # every OTHER character in query is lowercase. This still needs a pass
    # deciding which characters correspond to pattern, effectively the same
    # greedy walk, just framed as an exhaustive subsequence search.
    def backtrack(qi, pi):
        if pi == len(pattern):
            return all(c.islower() for c in query[qi:])
        if qi == len(query):
            return False
        if query[qi] == pattern[pi]:
            if backtrack(qi + 1, pi + 1):                       # try consuming this as a pattern match
                return True
        if query[qi].islower():
            return backtrack(qi + 1, pi)                          # try skipping this as an insertion
        return False
    return backtrack(0, 0)

