def is_match(query, pattern):
    i = 0                                                       # pattern pointer
    for c in query:
        if i < len(pattern) and pattern[i] == c:
            i += 1                                                # matched, advance pattern pointer
        elif c.isupper():
            return False                                            # uppercase must match, cannot be inserted
    return i == len(pattern)                                     # pattern fully consumed?

def camel_match(queries, pattern):
    return [is_match(q, pattern) for q in queries]

