public class Main {
    static boolean isMatch(String query, String pattern) {
        int i = 0;                                                    // pattern pointer
        for (char c : query.toCharArray()) {
            if (i < pattern.length() && pattern.charAt(i) == c) {
                i++;                                                     // matched, advance pattern pointer
            } else if (Character.isUpperCase(c)) {
                return false;                                              // uppercase must match, cannot be inserted
            }
        }
        return i == pattern.length();                                 // pattern fully consumed?
    }

    static boolean[] camelMatch(String[] queries, String pattern) {
        boolean[] res = new boolean[queries.length];
        for (int k = 0; k < queries.length; k++) res[k] = isMatch(queries[k], pattern);
        return res;
    }
}

