#include <bits/stdc++.h>
using namespace std;

bool isMatch(const string& query, const string& pattern) {
    int i = 0;                                                     // pattern pointer
    for (char c : query) {
        if (i < (int)pattern.size() && pattern[i] == c) {
            i++;                                                       // matched, advance pattern pointer
        } else if (isupper(c)) {
            return false;                                                // uppercase must match, cannot be inserted
        }
    }
    return i == (int)pattern.size();                                // pattern fully consumed?
}

vector<bool> camelMatch(vector<string>& queries, string pattern) {
    vector<bool> res;
    for (auto& q : queries) res.push_back(isMatch(q, pattern));
    return res;
}
